  // ===== WHATSAPP RECORDING - START =====
  async function startRecording(e: any) {
    if (isBlocked) return;
    if (e) { e.preventDefault(); const t = e.touches ? e.touches[0] : e; startX.current = t.clientX; startY.current = t.clientY; }
    isCancel.current = false; setCancelSlide(false); setLockSlide(false); setLocked(false); setPaused(false); setStopped(false);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const rec = new MediaRecorder(stream); recRef.current = rec; recChunks.current = [];
      rec.ondataavailable = (ev: any) => { if (ev.data.size > 0) recChunks.current.push(ev.data); };
      rec.start(); setRecording(true); setRecTime(0);
      if (recTimer.current) clearInterval(recTimer.current);
      recTimer.current = setInterval(() => { setRecTime((t) => { if (t >= 1800) { finishRecording(true); return t; } return t + 1; }); }, 1000);
    } catch (err) { alert("Give mic permission!"); }
  }
  // Swipe - Up = Lock, Left = Cancel
  function onMicMove(e: any) {
    if (!recording || locked) return;
    const t = e.touches ? e.touches[0] : e; if (!t) return;
    const dx = t.clientX - startX.current; const dy = t.clientY - startY.current;
    if (dx < -70) { isCancel.current = true; setCancelSlide(true); setLockSlide(false); }
    else if (dy < -70) { setLockSlide(true); setCancelSlide(false); }
    else { isCancel.current = false; setCancelSlide(false); setLockSlide(false); }
  }
  // Finger Chhoro - Agar Lock nahi to Send, Cancel hai to Delete
  function onMicRelease(e: any) {
    if (!recording) return;
    if (e) e.preventDefault();
    if (lockSlide) { setLocked(true); setLockSlide(false); setCancelSlide(false); return; }
    if (locked) return;
    if (isCancel.current) { finishRecording(false); }
    else { finishRecording(true); }
  }
  function togglePause() {
    if (!recRef.current) return;
    if (paused) { try { recRef.current.resume(); } catch (e) { } setPaused(false); if (recTimer.current) clearInterval(recTimer.current); recTimer.current = setInterval(() => setRecTime((t) => t + 1), 1000); }
    else { try { recRef.current.pause(); } catch (e) { } setPaused(true); if (recTimer.current) clearInterval(recTimer.current); }
  }
  function stopLocked() { setStopped(true); if (recRef.current) { try { recRef.current.pause(); } catch (e) { } } if (recTimer.current) clearInterval(recTimer.current); }
  function resumeAfterStop() { setStopped(false); setPaused(false); if (recRef.current) { try { recRef.current.resume(); } catch (e) { } } recTimer.current = setInterval(() => setRecTime((t) => t + 1), 1000); }
  // ===== FIXED - Voice ko Base64 me Save - Hamesha Chalegi =====
  function finishRecording(sendIt: boolean) {
    if (!recRef.current) return;
    if (recTimer.current) clearInterval(recTimer.current);
    const rec = recRef.current; const curTime = recTime;
    rec.onstop = () => {
      try { if (rec.stream) rec.stream.getTracks().forEach((t: any) => t.stop()); } catch (e) { }
      if (sendIt && curTime > 0 && recChunks.current.length) {
        const blob = new Blob(recChunks.current, { type: "audio/webm" });
        const reader = new FileReader();
        reader.onloadend = () => { pushMsg({ type: "voice", url: reader.result, duration: formatTime(curTime), time: "Now", listened: false }); };
        reader.readAsDataURL(blob);
      }
    };
    try { if (rec.state !== "inactive") rec.stop(); } catch (e) { }
    setRecording(false); setLocked(false); setPaused(false); setStopped(false); setCancelSlide(false); setLockSlide(false); isCancel.current = false; setRecTime(0);
  }
