  async function startCall(n: string, t: string) { if (blocked.includes(n)) { alert(n + " Blocked!"); return; } setS(n); setCallType(t); setCall(n); setCamOn(true); setMicOn(true); if (t === "Video") { try { const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true }); streamRef.current = stream; setTimeout(() => { if (videoRef.current) videoRef.current.srcObject = stream; }, 200); } catch (e) { alert("Give camera permission!"); } } }
